const a={breadcrumbSystems:"Sistemler",switcherLabel:"Ücretli reklam hizmetleri",cta:{book:"Ücretsiz reklam strateji görüşmesi planlayın",whatsapp:"WhatsApp'tan yazın"},hero:{checks:["Ücretsiz 30 dakikalık strateji görüşmesi","Reklam hesabı sizin","Anlaşılır dille haftalık rapor"]},caseBox:{label:"Kurucumuzun yönettiği klinik reklamları",desc:"Avrupa'dan ve Körfez ülkelerinden uluslararası hasta kabul eden klinikler için kampanya yapısı, hedefleme, kreatifler ve bütçe."},problemsSection:{eyebrow:"Reklam bütçesi nereye gidiyor",title:"Kliniklerin {{platform}} reklamları neden çoğu zaman hastaya dönüşmüyor",lead:"Sorun nadiren yalnızca reklamlardadır. Bütçe, tıklama ile konsültasyon arasında kaybolur."},funnelSection:{eyebrow:"Farkımız",title:"Reklam ve yanıt, tek bir sistem olarak yönetilir",lead:"Çoğu ajans potansiyel müşteriyi getirdiği noktada durur. Biz kampanyayı WhatsApp AI'a bağlarız; gece yarısı tıklayan hasta anında yanıt alır ve reklam platformu planlanan konsültasyonlardan öğrenir.",optional:"WhatsApp AI isteğe bağlıdır ve ayrıca ücretlendirilir.",optionalLink:"WhatsApp AI'ı inceleyin"},funnel:[{title:"Reklam",desc:"Doğru hastaya, kendi dilinde ve kendi pazarında gösterilir."},{title:"Talep",desc:"Anında form, açılış sayfası ya da WhatsApp'ı açan tek bir tıklama."},{title:"3 saniyenin altında yanıt",desc:"WhatsApp AI 7/24, 40+ dilde yanıt verir."},{title:"Ön değerlendirme",desc:"Tedavi, bütçe ve seyahat tarihleri toplanır; ciddi hastalar ekibinize yönlendirilir."},{title:"Randevu",desc:"Konsültasyon takviminize eklenir ve reklam platformuna geri bildirilir."}],included:{eyebrow:"Neler dahil",title:"{{platform}} Ads yönetimi, sizin yerinize"},methodSection:{eyebrow:"Nasıl çalışıyoruz",title:"Araştır, hedefle, dönüştür",step:"ADIM 0{{n}}"},faqSection:{badge:"SSS",title:"{{platform}} Ads hakkında sorular",otherQ:"{{platform}} reklamları da mı yayınlıyorsunuz?",otherLink:"Klinikler için {{platform}} Ads'i inceleyin"},finalCta:{title:"{{platform}} reklam bütçenizi planlanmış konsültasyonlara dönüştürün",lead:"Ücretsiz 30 dakikalık bir strateji görüşmesi planlayın. Tedavilerinize, pazarlarınıza ve mevcut kampanyalarınıza bakar, ilk olarak neyi değiştireceğimizi açıkça söyleriz."},faqs:[{question:"Maliyeti nedir?",answer:"İki kalem vardır. Reklam bütçesini doğrudan {{platform}} platformuna siz ödersiniz; böylece her euro kampanyalara gider. Yönetim ücretimiz, kampanya, ülke ve dil sayısına göre ücretsiz 30 dakikalık bir strateji görüşmesinin ardından belirlenir. Kampanyaların optimizasyon için yeterli veri toplayabilmesi adına ayda en az {{minSpend}} reklam bütçesi öneriyoruz."},{question:"Reklam hesabı kime ait?",answer:"Size. Kampanyalar kendi reklam hesabınızda, kendi ödeme yönteminizle yayınlanır; biz hesapta iş ortağı olarak çalışırız. Bir gün birlikte çalışmayı bırakırsanız hesap, kitleler ve tüm veriler sizde kalır."},{question:"Sonuçları ne zaman görürüz?",answer:"Takip altyapısı kurulduktan sonra kampanyalar yaklaşık iki hafta içinde yayına girer. İlk 2–4 hafta, platformun veri topladığı öğrenme dönemidir; iyileşmenin büyük kısmı sonraki 2–3 aylık test sürecinde gelir. Hesabınızı, teklifinizi ve pazarınızı görmeden talep başına maliyet sözü vermeyiz."},{question:"Reklamlardan gelen taleplere siz mi yanıt veriyorsunuz?",answer:"Çoğu ajansın atladığı kısım tam olarak bu. Talepler doğrudan Webimot WhatsApp AI'a aktarılabilir; sistem 3 saniyenin altında, 7/24 ve 40+ dilde yanıt verir, hastanın ön değerlendirmesini yapar ve konsültasyonu planlar. İsteğe bağlıdır, ancak reklam bütçesi genellikle burada kaybolur: bir saat içinde kimsenin yanıtlamadığı bir talep büyük ölçüde kaybedilmiş demektir."},{question:"Hangi ülke ve dilleri hedefleyebilirsiniz?",answer:"Platformun izin verdiği her pazarı. Medikal turizm klinikleri için yaygın pazarlar Almanya, Birleşik Krallık, Hollanda, Fransa ve Körfez ülkeleridir; reklamlar ve açılış sayfaları hastanın kendi dilinde hazırlanır. Kampanyalar ülkelere göre ayrılır; böylece her pazarın maliyetini ve getirdiği randevuları görebilirsiniz."}],"meta-ads":{minSpend:"€500",eyebrow:"Meta Ads · Facebook ve Instagram",headline:"Yalnızca gelen kutunuzu değil, konsültasyon takviminizi dolduran Meta reklamları.",lead:"Klinikler ve medikal turizm sağlayıcıları için, hastanın tüm yolculuğu etrafında kurgulanan Facebook ve Instagram kampanyaları: reklam, WhatsApp görüşmesi ve planlanan konsültasyon. Her talep 3 saniyenin altında yanıtlanır.",problems:["Anında formlardan gelen talepler saat 23:00'te düşer ve ertesi güne kadar kimse yanıt vermez. O sırada hasta üç farklı kliniğe daha yazmıştır.","Kampanya ucuz talep için optimize edilir; gelen kutusu tedavi için seyahat etmeye hiç niyeti olmayan kişilerle dolar.","Sağlık reklamları Meta'nın öncesi-sonrası görselleri ve kişisel özelliklerle ilgili kurallarını ihlal ettiği için reklamlar reddedilir ya da hesap kısıtlanır.","Hangi kampanyanın planlanmış bir konsültasyon getirdiğini kimse söyleyemez; bu yüzden bütçe, talep başına en ucuz görünen kampanyaya gider."],deliverables:[{title:"Strateji ve kitle araştırması",desc:"Tedavileriniz, fiyatlarınız ve pazarlarınız bir kampanya planına dönüşür: hangi ülkeler, hangi kitleler, hangi teklif, bütçe nasıl dağıtılacak."},{title:"Kreatifler ve metinler",desc:"Hastanın dilinde, Meta'nın sağlık reklamı politikalarına uygun yazılmış görsel ve video reklamlar ile metinler."},{title:"Talep formları ve WhatsApp'a tıklama",desc:"Ön değerlendirme sorularıyla anında formlar ya da doğrudan kliniğinizle WhatsApp sohbeti açan reklamlar."},{title:"Randevuya kadar uzanan takip",desc:"Meta Pixel, Conversions API ve CRM olayları; böylece platform yalnızca form doldurmalardan değil, planlanan konsültasyonlardan öğrenir."},{title:"Test ve optimizasyon",desc:"Her hafta kreatif, kitle ve teklif testleri; bütçe konsültasyon getiren kampanyalara kaydırılır."},{title:"Haftalık rapor",desc:"Kampanya ve ülke bazında harcama, talepler, nitelikli talepler ve konsültasyonlar; anlaşılır bir dille."}],method:[{label:"Araştır",points:["Meta Reklam Kitaplığı'nda rakip reklamları","En iyi hastalarınızın ortak özellikleri","Alanınızda işe yarayan formatlar ve yaklaşımlar","Pazara göre teklif ve fiyat konumlandırması"]},{label:"Hedefle",points:["Ülke bazlı kampanyalar: DE, UK, NL, Körfez ve diğerleri","Gerçek hastalardan oluşturulan benzer kitleler","Web sitesi ve Instagram ziyaretçilerine yeniden hedefleme","Dile özel kreatifler ve formlar"]},{label:"Dönüştür",points:["Ön değerlendirme sorulu talep formları","7/24 anında WhatsApp yanıtı","Meta'ya geri gönderilen dönüşüm olayları","Reklam yorgunluğuna karşı aylık kreatif yenileme"]}],policy:{title:"Meta'nın sağlık reklamı kurallarına uygun kurgulanır",desc:"Meta, bir kişinin sağlık durumu hakkında bilgi sahibi olunduğunu ima eden reklamları kısıtlar; estetik ve tıbbi işlemlerde öncesi-sonrası görselleri ve bazı iddiaları sınırlar. Baştan itibaren bu kurallar içinde yazar ve tasarlarız; böylece kampanyalar öğrenme döneminin ortasında durdurulmaz."}},"google-ads":{minSpend:"€1.000",eyebrow:"Google Ads · Arama ve YouTube",headline:"Tedavinizi zaten arayan hastalar için Google Ads.",lead:'Klinikler ve medikal turizm sağlayıcıları için satın alma niyetini hedefleyen arama kampanyaları; örneğin "saç ekimi Türkiye fiyat" gibi aramalar, her hastanın dilinde ve pazarında, planlanan konsültasyona kadar uzanan takiple.',problems:["Geniş anahtar kelimeler bütçeyi öğrencilere, iş arayanlara ve ücretsiz bilgi karşılaştıranlara harcar.","Reklamlar Almanca ve Arapça konuşanları İngilizce bir sayfaya gönderir ve tıklama boşa gider.","Dönüşüm takibi sayfa görüntülemelerini veya buton tıklamalarını sayar; Google yanlış hedef için optimizasyon yapar.","Sağlık reklamları Google'ın sağlık ve ilaç politikası nedeniyle onaylanmaz ya da önemli ülkelere hiç ulaşmaz."],deliverables:[{title:"Anahtar kelime ve pazar araştırması",desc:"Tedavi, ülke ve dil bazında satın alma niyeti taşıyan arama terimleri ve ilk günden boşa giden tıklamaları durduran negatif anahtar kelime listesi."},{title:"Kampanya yapısı",desc:"Tedaviye ve ülkeye göre ayrılmış kampanyalar; böylece her pazarın maliyetini ve getirdiği randevuları görürsünüz."},{title:"Hastanın dilinde reklam metinleri",desc:"Her pazar için yazılan ve Google'ın sağlık politikasına göre kontrol edilen duyarlı arama reklamları ve öğeler."},{title:"Açılış sayfası önerileri",desc:"Her açılış sayfasının dönüşüm için neye ihtiyacı olduğu: fiyat sinyalleri, güven unsurları, WhatsApp butonu, sayfa hızı."},{title:"Randevuya kadar takip",desc:"Google Ads dönüşümleri, GA4 ve CRM'inizden çevrimdışı dönüşüm aktarımı; böylece teklif stratejisi konsültasyonlardan öğrenir."},{title:"Haftalık rapor",desc:"Kampanya bazında harcama, tıklamalar, talepler ve konsültasyonlar; ayrıca eklediğimiz veya engellediğimiz arama terimleri."}],method:[{label:"Araştır",points:["Anahtar kelime niyet haritası: alıcı mı, gezinen mi","Rakip reklamlar ve açılış sayfaları","Ülke ve dile göre arama hacmi","Yayından önce negatif anahtar kelimeler"]},{label:"Hedefle",points:["Yüksek niyetli tedavi ve fiyat aramaları","Coğrafi hedefleme: Almanya, Birleşik Krallık, Hollanda, Körfez ve diğerleri","Cihaz ve günün saatine göre teklif ayarlamaları","Geçmiş ziyaretçilere yeniden pazarlama"]},{label:"Dönüştür",points:["Her dilde test edilen reklam metinleri","Dönüşüm için kurgulanmış açılış sayfaları","Kampanya bazında WhatsApp ve arama takibi","Tıklamalara değil, planlanan konsültasyonlara göre teklif"]}],policy:{title:"Google'ın sağlık politikasına uygun kurgulanır",desc:"Google, bazı sağlık ve ilaç reklamlarını ülkeye ve tedaviye göre kısıtlar; doğru iddialar ve açılış sayfaları ister. Yayından önce her pazarın kurallarını kontrol ederiz; böylece kampanyalar hastalarınızın gerçekten arama yaptığı yerlerde yayınlanır."}}},e={adsPage:a};export{a as adsPage,e as default};
